'use client';
import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { ShieldCheck } from 'lucide-react';
import { useAuth } from '@/context/AuthContext'; // We'll leverage context for persistency later, or local state for now

export default function AdminLogin() {
  const router = useRouter();
  const [passcode, setPasscode] = useState('');
  const [error, setError] = useState('');

  const handleLogin = (e) => {
    e.preventDefault();
    if (passcode === 'admin123') { 
      // Set a cookie or localStorage to persist admin session
      localStorage.setItem('admin_auth', 'true');
      document.cookie = "admin_auth=true; path=/";
      router.push('/admin');
    } else {
      setError('Invalid Passcode');
    }
  };

  return (
      <main style={{ height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#0f172a' }}>
        <div className="glass" style={{ padding: '3rem', width: '100%', maxWidth: '400px', textAlign: 'center', border: '1px solid rgba(255,255,255,0.1)' }}>
          <div style={{ display: 'inline-flex', padding: '1rem', background: 'rgba(0, 210, 211, 0.1)', borderRadius: '50%', marginBottom: '1.5rem' }}>
            <ShieldCheck size={40} color="var(--primary)" />
          </div>
          <h1 style={{ marginBottom: '0.5rem', color: '#fff' }}>Admin Portal</h1>
          <p style={{ color: '#94a3b8', marginBottom: '2rem' }}>Secure Access Only</p>
          
          <form onSubmit={handleLogin}>
            <div style={{ marginBottom: '1.5rem', textAlign: 'left' }}>
                <input 
                  type="password" 
                  placeholder="Enter Passcode" 
                  value={passcode}
                  onChange={(e) => setPasscode(e.target.value)}
                  style={{ 
                    width: '100%', 
                    padding: '1rem', 
                    background: 'rgba(255,255,255,0.05)', 
                    border: '1px solid rgba(255,255,255,0.1)', 
                    color: '#fff',
                    outline: 'none',
                    borderRadius: '8px',
                    fontSize: '1rem'
                  }} 
                />
            </div>
            
            {error && <p style={{ color: '#ef4444', marginBottom: '1rem', fontSize: '0.9rem' }}>{error}</p>}
            
            <button className="btn btn-primary" style={{ width: '100%', padding: '1rem', fontSize: '1rem' }}>Login to Dashboard</button>
          </form>
        </div>
      </main>
  );
}
